/**
 * TASK: Finish a tiny arithmetic expression tree. Expr, Num and Add are
 * provided -- do not edit them. You must add two more subclasses of Expr as
 * static nested classes inside ArithmeticTreeBuilder, and wire up the factories.
 *
 * Every node answers three questions:
 *   eval()        its numeric value
 *   precedence()  3 for a number, 2 for multiplication, 1 for + and -
 *   render()      the expression as text, with the FEWEST brackets that still
 *                 mean the same thing
 *
 * The inherited helper renderChild(child) already brackets a child that binds
 * more loosely than its parent, so:
 *
 *   mul(num(2), add(num(3), num(4))).render()  ->  "2 * (3 + 4)"
 *   add(num(2), mul(num(3), num(4))).render()  ->  "2 + 3 * 4"
 *
 * Subtraction has one extra trap. Its RIGHT child needs brackets whenever that
 * child is itself a + or a -, because subtraction does not associate:
 *
 *   sub(num(10), sub(num(4), num(1))).render() ->  "10 - (4 - 1)"   (= 7)
 *   sub(sub(num(10), num(4)), num(1)).render() ->  "10 - 4 - 1"     (= 5)
 *
 * Write Mul and Sub, then make mul(...) and sub(...) return them.
 */
abstract class Expr {

    public abstract double eval();

    /** 3 = a plain number, 2 = multiplication, 1 = addition or subtraction. */
    public abstract int precedence();

    public abstract String render();

    /** Brackets a child only when it binds more loosely than this node. */
    protected String renderChild(Expr child) {
        if (child.precedence() < precedence()) {
            return "(" + child.render() + ")";
        }
        return child.render();
    }
}

class Num extends Expr {
    private final double value;

    Num(double value) {
        this.value = value;
    }

    @Override
    public double eval() {
        return value;
    }

    @Override
    public int precedence() {
        return 3;
    }

    @Override
    public String render() {
        if (value == Math.rint(value)) {
            return String.valueOf((long) value);
        }
        return String.valueOf(value);
    }
}

class Add extends Expr {
    private final Expr left;
    private final Expr right;

    Add(Expr left, Expr right) {
        this.left = left;
        this.right = right;
    }

    @Override
    public double eval() {
        return left.eval() + right.eval();
    }

    @Override
    public int precedence() {
        return 1;
    }

    @Override
    public String render() {
        return renderChild(left) + " + " + renderChild(right);
    }
}

