public class ArithmeticTreeBuilderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static Object round2(java.util.function.Supplier<Double> body) {
        try {
            return Math.round(body.get() * 100.0) / 100.0;
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        check("mul evaluates", 12.0,
                round2(() -> ArithmeticTreeBuilder.mul(ArithmeticTreeBuilder.num(3),
                        ArithmeticTreeBuilder.num(4)).eval()));
        check("sub evaluates", 6.0,
                round2(() -> ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(10),
                        ArithmeticTreeBuilder.num(4)).eval()));
        check("mul precedence is 2", 2,
                safe(() -> ArithmeticTreeBuilder.mul(ArithmeticTreeBuilder.num(3),
                        ArithmeticTreeBuilder.num(4)).precedence()));
        check("sub precedence is 1", 1,
                safe(() -> ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(3),
                        ArithmeticTreeBuilder.num(4)).precedence()));
        check("a looser child is bracketed", "2 * (3 + 4)",
                safe(() -> ArithmeticTreeBuilder.mul(ArithmeticTreeBuilder.num(2),
                        ArithmeticTreeBuilder.add(ArithmeticTreeBuilder.num(3),
                                ArithmeticTreeBuilder.num(4))).render()));
        check("a tighter child is not", "2 + 3 * 4",
                safe(() -> ArithmeticTreeBuilder.add(ArithmeticTreeBuilder.num(2),
                        ArithmeticTreeBuilder.mul(ArithmeticTreeBuilder.num(3),
                                ArithmeticTreeBuilder.num(4))).render()));
        check("a subtraction on the right needs brackets", "10 - (4 - 1)",
                safe(() -> ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(10),
                        ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(4),
                                ArithmeticTreeBuilder.num(1))).render()));
        check("and that expression is 7", 7.0,
                round2(() -> ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(10),
                        ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(4),
                                ArithmeticTreeBuilder.num(1))).eval()));
        check("a subtraction on the left does not", "10 - 4 - 1",
                safe(() -> ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(10),
                        ArithmeticTreeBuilder.num(4)), ArithmeticTreeBuilder.num(1)).render()));
        check("an addition on the right of a minus is bracketed too", "10 - (4 + 1)",
                safe(() -> ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(10),
                        ArithmeticTreeBuilder.add(ArithmeticTreeBuilder.num(4),
                                ArithmeticTreeBuilder.num(1))).render()));
        check("a looser left child of a product is bracketed", "(5 - 2) * 3",
                safe(() -> ArithmeticTreeBuilder.mul(ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(5),
                        ArithmeticTreeBuilder.num(2)), ArithmeticTreeBuilder.num(3)).render()));
        check("nested products stay flat", "2 * 3 * 4",
                safe(() -> ArithmeticTreeBuilder.mul(ArithmeticTreeBuilder.num(2),
                        ArithmeticTreeBuilder.mul(ArithmeticTreeBuilder.num(3),
                                ArithmeticTreeBuilder.num(4))).render()));
        check("a big mixed tree evaluates", 23.0,
                round2(() -> ArithmeticTreeBuilder.add(
                        ArithmeticTreeBuilder.mul(ArithmeticTreeBuilder.num(5), ArithmeticTreeBuilder.num(4)),
                        ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(6),
                                ArithmeticTreeBuilder.num(3))).eval()));
        check("and renders without stray brackets", "5 * 4 + 6 - 3",
                safe(() -> ArithmeticTreeBuilder.add(
                        ArithmeticTreeBuilder.mul(ArithmeticTreeBuilder.num(5), ArithmeticTreeBuilder.num(4)),
                        ArithmeticTreeBuilder.sub(ArithmeticTreeBuilder.num(6),
                                ArithmeticTreeBuilder.num(3))).render()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

