public class ArithmeticTreeBuilder {

    static class Mul extends Expr {
        private final Expr left;
        private final Expr right;

        Mul(Expr left, Expr right) {
            this.left = left;
            this.right = right;
        }

        @Override
        public double eval() {
            return left.eval() * right.eval();
        }

        @Override
        public int precedence() {
            return 2;
        }

        @Override
        public String render() {
            return renderChild(left) + " * " + renderChild(right);
        }
    }

    static class Sub extends Expr {
        private final Expr left;
        private final Expr right;

        Sub(Expr left, Expr right) {
            this.left = left;
            this.right = right;
        }

        @Override
        public double eval() {
            return left.eval() - right.eval();
        }

        @Override
        public int precedence() {
            return 1;
        }

        @Override
        public String render() {
            String rightText;
            if (right.precedence() <= precedence()) {
                rightText = "(" + right.render() + ")";
            } else {
                rightText = renderChild(right);
            }
            return renderChild(left) + " - " + rightText;
        }
    }

    public static Expr num(double value) {
        return new Num(value);
    }

    public static Expr add(Expr left, Expr right) {
        return new Add(left, right);
    }

    public static Expr mul(Expr left, Expr right) {
        return new Mul(left, right);
    }

    public static Expr sub(Expr left, Expr right) {
        return new Sub(left, right);
    }
}
